local UIMazeStoryEventResultNode = Class("UIMazeStoryEventResultNode")
function UIMazeStoryEventResultNode:__init() 
    self._itemLoader = nil
end

function UIMazeStoryEventResultNode:__delete()
    self._itemLoader = nil
end

function UIMazeStoryEventResultNode:Awake()
end

function UIMazeStoryEventResultNode:Start()
end

function UIMazeStoryEventResultNode:RefreshTitle(desc)
    CfUtils.FillText(self.resultDesc, desc)
end

function UIMazeStoryEventResultNode:RefreshEffect(rewardType, resultData)
    if not resultData then
        return
    end
    KTool.SetActive(self.effect, true)
    local curses = resultData.curses
    local relics = resultData.relics
    local rewards = resultData.rewards
    local mazeGoods = resultData.mazeGoods

    if rewardType == Constants.MazeRewardType.MazeItem then
        CfUtils.FillText(self.resultDesc, localize("获得了物品:"))
        self:FillMazeReward(mazeGoods)
    elseif rewardType == Constants.MazeRewardType.CommonItem then
        CfUtils.FillText(self.resultDesc, localize("获得了物品:"))

        GoodsUtils.DrawRewards(rewards)
        --这个都是外部的奖励  显示只取第一个
        for k, v in pairs(rewards[1]) do
            local item = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
            if item then
                CfUtils.FillText(self.name, item.name)
                CfUtils.FillText(self.desc, item.desc)
                self:RefreshItemNode(self.item, v.goodsId, checkString(v.num), 1)
            end
        end
    elseif rewardType == Constants.MazeRewardType.MazeRelics then
        CfUtils.FillImage(self.effectIma, "uiatlas/Maze/MazeStory/maze_event_img_result_good.png")
        CfUtils.FillText(self.resultDesc, localize("获得了情报效应:"))
        self:FillMazeReward(relics)
    elseif rewardType == Constants.MazeRewardType.MazeCurses then
        CfUtils.FillImage(self.effectIma, "uiatlas/Maze/MazeStory/maze_event_img_result_bad.png")
        CfUtils.FillText(self.resultDesc, localize("受到了谣言效应:"))
        self:FillMazeReward(curses)
    end
end

--绘制迷宫的奖励
function UIMazeStoryEventResultNode:FillMazeReward(data)
    if not data then
        return
    end
    for k, v in pairs(data) do
        local item = GoodsConfMgr:GetInstance():GetGoodsVoById(k, Constants.IDArea.Maze)
        if item then
            CfUtils.FillText(self.name, item.name)
            CfUtils.FillText(self.desc, item.description)
            self:RefreshItemNode(self.item, k, checkString(v), nil, Constants.IDArea.Maze)
        end
    end
end

function UIMazeStoryEventResultNode:RefreshItemNode(goPar, itemId, num, scale, idAreaType, cb, id)
    if not goPar then
        return
    end

    if not self._itemLoader then
        self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
    end
    if self._itemLoader.IsSuccess then
        local go = goPar.transform:Find("item")
        if not go then 
            go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, goPar)
            go.name = "item"
        end
        if go then
            CfUtils.RefeshGoodGo(go, itemId, num, scale, idAreaType, cb, id)
        end
    end
end

function UIMazeStoryEventResultNode:OnSelect()
    if self._selectCb then
        self._selectCb()
    end
end

function UIMazeStoryEventResultNode:OnClick(value)
    KTool.SetActive(self.select, value)

    if self._clickCb then
        self._clickCb()
    end
end

function UIMazeStoryEventResultNode:OnDestroy()
    if not isNull(self._itemLoader) then
        self._itemLoader:Release()
        self._itemLoader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMazeStoryEventResultNode
